export interface BrowserUrlPolicyOptions {
  resolveHost?: (hostname: string) => Promise<BrowserResolvedEndpoint[]>;
  reverseHost?: (address: string) => Promise<string[]>;
  getDnsServers?: () => string[];
  strictNetworkAvailable?: boolean;
